import * as Effect from "effect/Effect";
import type * as Stream from "effect/Stream";

export interface EventRecord {
  readonly detail: unknown;
}

export interface EventRouteProps {
  readonly id?: string;
  readonly description?: string;
}

export const consumeBusEvents = (...args: any[]) => {
  // The handler is the LAST positional argument.
  const process = args[args.length - 1] as (events: Stream.Stream<EventRecord, never, never>) => Effect.Effect<void, never, never>;
  return Effect.suspend(() => Effect.as(Effect.void, args.length - 1)).pipe(Effect.tap(() => process));
};

