import type * as Effect from "effect/Effect";
import type * as Stream from "effect/Stream";
import {
  consumeBusEvents,
  type EventRecord,
  type EventRouteProps,
} from "../EventBridge/EventSource.ts";

export interface ExpiryEventSourceProps extends EventRouteProps {
  readonly certificateArns?: ReadonlyArray<string>;
}

export const expiryPattern = (props: ExpiryEventSourceProps) => ({
  source: ["aws.acm"],
  "detail-type": ["ACM Certificate Approaching Expiration"],
  ...(props.certificateArns !== undefined ? { resources: [...props.certificateArns] } : {}),
});

export const consumeExpiryEvents = <StreamReq = never, Req = never>(
  props: ExpiryEventSourceProps,
  process: (events: Stream.Stream<EventRecord, never, StreamReq>) => Effect.Effect<void, never, Req>,
) =>
  consumeBusEvents(
    props.id ?? "AcmExpiryEvents",
    expiryPattern(props),
    { description: props.description },
    process,
  );

